"""Optional, bounded gifts: original designs inspired by a broad talent/blessing menu."""

def definitions():
    rows=[]
    def add(name,group,description,attributes=None,skills=None,resources=None,ability=None,resistances=None,vulnerabilities=None):
        rows.append(dict(name=name,group=group,description=description,attributes=attributes or {},skills=skills or {},resources=resources or {},ability=ability,resistances=resistances or [],vulnerabilities=vulnerabilities or []))
    def move(name,text,bonus=5,cooldown=5):return dict(name=name,description=text,bonus=bonus,cooldown=cooldown)

    g='Instinct and Ingenuity'
    add('Living Index',g,'An unusually faithful memory for material you actually studied. Revisit a remembered detail with remarkable clarity; unknown facts still require evidence.',{'logic':1},{'investigation':5},ability=move('Margin Remembered','Carefully reconstruct a previously observed page, route detail or conversation relevant to the present investigation. Resolve an investigation check with this bonus; missing observations and a misleading original remain missing or misleading. Costs 4 Stamina for a committed concentrated attempt.',5,6))
    add('Trouble in the Air',g,'Your attention catches the small signs that something nearby is about to go wrong. It supplies an unusually sharp warning instinct, not a picture of every hidden threat.',{'intuition':1},{'Perception':4},ability=move('Before the Glass Falls','Use a sound, motion or other plausible nearby cue to notice an immediate developing hazard. Resolve Perception with this bonus. It reveals only what that cue can support and does not automatically evade an attack or identify an unseen culprit. Costs 5 Stamina.',5,5))
    add('Silver-Tongued Improviser',g,'You find a workable phrase when a conversation goes sideways. Quick invention helps you speak; the listener remains free to disbelieve or refuse.',{'empathy':1},{'persuasion':4,'Deception':2})
    add('Price of Everything',g,'A practiced eye for workmanship and a head for prices make you a memorable bargaining partner. An unfamiliar magical effect still needs proper examination.',{'logic':1},{'Trade':5,'Perception':2})
    add('Practical Savant',g,'You see how ordinary mechanisms fit together and enjoy making stubborn things work. This gift supports actual tools and materials rather than replacing them.',{'logic':1},{'Magitech':5,'investigation':2})
    add('The Patient Hand',g,'Your hands remain steady during delicate care and careful mixture preparation. You are especially comfortable with work that rewards a measured pace.',{'finesse':1},{'Medicine':3,'Alchemy':3})
    add('Roadwise',g,'Travel details stick: a change in weather, a fraying bridge line, a landmark seen from the return direction. Experience makes unfamiliar routes easier to assess.',{'intuition':1},{'survival':5,'Perception':2})
    add('Beastward Manner',g,'Animals often find your movements easier to read. You are good at patient handling, while frightened, hungry and territorial creatures retain their own priorities.',{'empathy':1},{'Animal Handling':5,'Insight':2})
    add('Perfect Pitch, Imperfect Manners',g,'Your ear catches tiny changes in pitch and timing. Music and sound work come readily; you sometimes notice an off-key note before the speaker finishes their point.',{}, {'performance':5,'Perception':3})
    add('Hearth-Blessed Palate',g,'You distinguish a surprising range of flavors and aromas, and turn modest ingredients into satisfying food. Unknown poison is not automatically recognizable by taste.',{'intuition':1},{'Cooking':5,'Perfumery':2})
    add('Unflappable Reader',g,'You remain unusually clear-headed while evaluating pressure, bluff and conflicting accounts. Your reading of a person is still an inference.',{'logic':1},{'Insight':5,'Etiquette':2})
    add('Small Miracles of Order',g,'You have a gift for making a confusing practical task manageable: the right label, the missing step, the tool placed within reach.',{}, {'Tactics':3,'investigation':3,'Trade':2},{'Stamina':15})

    g='Martial Gifts'
    add('First Bell Reflex',g,'Your body answers a sudden danger before you have fully named it. A quick defensive technique gives that instinct a practical outlet.',{'finesse':1},{'acrobatics':3},ability=move('Late Bell Sidestep','Commit to a quick evasive step against an actual incoming threat, using acrobatics or the existing Finesse delivery appropriate to the action. Apply this bonus to one defend resolution, not both. A supplied miss or hit remains authoritative. Costs 6 Stamina.',5,5))
    add('Unmoved Heel',g,'You are difficult to hurry out of a position you have chosen to defend. Balance, preparation and a planted guard are your strengths.',{'force':1},{'Guarded Combat':4},{'Stamina':15},ability=move('The Door Holds','Set a real guard against one approaching attack or attempt to force passage. Resolve Guarded Combat with this bonus. It protects the space you can actually cover and gives no immunity, extra attack or automatic restraint. Costs 8 Stamina.',5,4))
    add('Duelist\'s Needle',g,'You notice brief openings in an opponent\'s guard and favor a precise answer. The technique works with an appropriate weapon or trained unarmed delivery.',{'finesse':1},{'Finesse Combat':4},ability=move('Needle Between Beats','Make one precise Finesse Combat attack against an actual reachable target, using this bonus. Describe a concrete opening rather than granting another action or ignoring armor. Costs 8 Stamina.',5,4))
    add('Giant\'s Grip',g,'Heavy tools and forceful weapons feel natural in your hands. Your frame is individually chosen; this talent does not require giant ancestry.',{'force':2},{'Force Combat':4},{'Mana':-15},ability=move('Gatepost Reprimand','Commit to one powerful Force Combat strike with an actual suitable weapon or trained bodily method. This bonus improves that one resolution; there is no additional knockback or structural destruction without the actual outcome. Costs 12 Stamina.',6,5))
    add('Wrestler\'s Sense',g,'You read leverage, balance and the moment a grip begins to fail. Practice helps you work with an opponent\'s movement rather than wishing them restrained.',{'force':1},{'Force Combat':3,'athletics':3},ability=move('Borrow the Balance','Attempt one close grapple, escape or controlled takedown through Force Combat or athletics as the actual action requires. Use the bonus once. Size, reach, footing and resistance still apply; no automatic restraint follows. Costs 8 Stamina.',5,4))
    add('Longshot Patience',g,'You settle quickly into the discipline of a deliberate ranged shot. Clear sight and a real projectile remain necessary.',{'finesse':1},{'Finesse Combat':4,'Perception':2},ability=move('One Quiet Line','Take a deliberate shot with an actual held bow, crossbow, sling or throwing weapon. Resolve the appropriate Finesse Combat attack with this bonus and spend real ammunition where applicable. No second shot or impossible line of sight. Costs 7 Stamina.',5,5))
    add('Chain-Dancer',g,'You understand the changing reach and momentum of flexible weapons. This is actual trained handling rather than an unexplained enchanted chain.',{'finesse':1},{'Finesse Combat':3,'acrobatics':3})
    add('Shield-Side Companion',g,'You are comfortable positioning yourself beside someone who needs protection. A cooperative guard works best when both people know the plan.',{'force':1},{'Guarded Combat':4,'Tactics':2})
    add('Breath of the Long Road',g,'A deep reserve of physical endurance supports demanding journeys and practiced techniques. It does not create passive recovery.',{}, {'athletics':3,'survival':2},{'Stamina':35})
    add('Merciful Finisher',g,'You are practiced at ending a dangerous exchange without insisting on a killing blow. Restraint is a method, not a compulsory moral code.',{}, {'Guarded Combat':3,'Force Combat':3,'Finesse Combat':2})
    add('Pursuer\'s Rhythm',g,'You are good at choosing a sustainable pace and recognizing the moment to close a gap. Terrain and actual distance still matter.',{'finesse':1},{'athletics':4,'survival':2},{'Stamina':15})
    add('Scar-Taught Resolve',g,'Past hard training has left a reserve of practical toughness and a habit of keeping your guard. Whether you have visible scars is your choice.',{'force':1},{'Guarded Combat':2},{'Health':30,'Mana':-10})

    g='Arcane Peculiarities'
    add('Blueprint Intuition',g,'Spell structures suggest themselves readily to you. Invention still requires Spellcraft, experimentation and the actual discipline needed to cast the result.',{'logic':1},{'spellcraft':6},ability=move('First Clean Draft','Make one actual Spellcraft design or revision attempt for a feasible working within your knowledge. Apply this bonus to the invention check. Difficult work still needs its real research and materials; a successful draft does not grant automatic mastery or a second free ability. Costs 8 Mana for a committed magical test.',5,6))
    add('Deep Reservoir',g,'You carry a larger usable Mana reserve in a physically less robust body. This changes capacity, not casting knowledge or recovery speed.',{}, {'spellcraft':2},{'Mana':55,'Health':-25})
    add('Cinder Familiarity',g,'A narrow fire-working comes readily to you, even if Fire is not your natural affinity. It is a selected learned gift, not broad elemental mastery.',{'passion':1},{'Fire Magic':4},ability=move('Lanternjaw Spark','Release a compact jaw-shaped snap of fire at one nearby reachable target. Resolve Fire Magic with this bonus. It is one ordinary attack with bounded flame, not a lasting creature or automatic ignition of the surroundings. Costs 9 Mana.',5,4))
    add('Water Threader',g,'Fine control over small currents is your unusual starting specialty. The gift supplies no Ice or blood magic.',{'passion':1},{'Water Magic':4},ability=move('Blue Needle Current','Direct a narrow current through available water or temporary conjured water at one reachable target. Resolve Water Magic with this bonus. A contested disarm or interruption is an alternative purpose, not extra free damage. Costs 9 Mana.',5,4))
    add('Listening Stone',g,'You have a feel for the resistance and grain of stone. Earthen shaping is learned through that narrow practical sensitivity.',{'passion':1},{'Earth Magic':4},ability=move('Stone Palm Courtesy','Raise or shift a small reachable section of ordinary earth into a low brace or obstacle. Resolve Earth Magic with this bonus when contested. It needs real footing or temporary conjuration and cannot collapse a building by declaration. Costs 10 Mana.',5,5))
    add('Wind-Written Gesture',g,'A moving hand and a small current of air seem to understand each other. You begin with a narrow useful wind technique.',{'passion':1},{'Wind Magic':4},ability=move('Ribbon Through the Air','Guide a precise gust to move one light unattended object, clear a small patch of smoke or attempt a bounded interruption. Resolve Wind Magic with this bonus if uncertain. No unrestricted flight or automatic disarm. Costs 8 Mana.',5,4))
    add('Storm Nerve',g,'You have an uncommon feel for the timing of a short electrical discharge. It does not make your body immune to lightning.',{'passion':1},{'Lightning Magic':4},ability=move('Bluebell Discharge','Send one short controlled electrical discharge at a nearby reachable target. Resolve Lightning Magic with this bonus. It gives no automatic stun, extra chain attack or safe passage through unrelated conductors. Costs 10 Mana.',5,5))
    add('Glasswinter Touch',g,'You can form delicate cold patterns with unusual care. Your starting technique is small and precise rather than a command over winter.',{'intuition':1},{'Ice Magic':4},ability=move('Winter\'s Fine Signature','Form a thin bounded frost pattern on one nearby surface or attempt one small ice attack. Resolve Ice Magic with this bonus. Freezing an entire person, room or body of water is outside its scope. Costs 10 Mana.',5,5))
    add('Gentle Radiance',g,'You are comfortable shaping clean light, including a brief concentrated ray. Light remains separate from Healing.',{'empathy':1},{'Light Magic':4},ability=move('Single Star Aperture','Shape one clear light or direct a narrow light ray at an actual target. Resolve Light Magic with this bonus when opposed. It grants no healing, automatic blindness or hidden-information revelation. Costs 9 Mana.',5,4))
    add('Green-Fingered Wonder',g,'A small practiced plant-working gives your care for growing things an unusual reach. Non-plant creatures are not healed by it.',{'empathy':1},{'Nature Magic':4},ability=move('Briar Buttonhole','Shape a small nearby plant into a useful tendril or attempt one limited thorn attack or binding. Resolve Nature Magic with this bonus. Resistance remains real; temporary conjured plant matter fades with the working. Costs 10 Mana.',5,5))
    add('Veilworker',g,'You have a knack for the small convincing illusion: an edge, a color, a misplaced sound. Interaction can expose a poor imitation.',{'intuition':1},{'Illusion Magic':4},ability=move('Borrowed Surface','Alter the apparent color or simple surface detail of one small visible object for the immediate scene. Resolve Illusion Magic with this bonus against scrutiny. It changes no physical property, inventory record, credential or ownership. Costs 8 Mana.',5,5))
    add('Quiet Between Spells',g,'You sense when a small working is poorly sustained and can attempt a narrow Void interruption. Powerful magic still needs a proportionate answer.',{'intuition':1},{'Void Magic':4},ability=move('Black Margin','Attempt to interrupt one nearby modest active working with a brief Void cut. Resolve Void Magic with this bonus against its actual strength. A failed interruption stands; it is no universal antimagic field or cancellation of resolved damage. Costs 12 Mana.',5,6))

    g='Blessings and Burdens'
    add('Blessing of the Last Lantern',g,'A quiet protective gift sharpens your attention when helping someone find a safe way out. Its origin can remain private or uncertain.',{'empathy':1},{'Perception':3,'Guarded Combat':3},{'Health':15})
    add('Blessing of Steady Hands',g,'An unusual calm supports careful treatment under pressure. It helps you use real medical knowledge and available supplies.',{'empathy':1},{'Medicine':5},{'Stamina':15},ability=move('The Stitch Holds','Perform one feasible nonmagical stabilization or treatment using actual Medicine, supplies and access to the patient. Apply this bonus to Medicine. Recovery follows the actual treatment; there is no resurrection, instant organ restoration or second healing award. Costs 6 Stamina.',5,5))
    add('Ashen Patronage',g,'Fire troubles you less, but cold bites deeper. The gift brings a substantial Mana reserve with an equally real elemental vulnerability.',{}, {'Fire Magic':4},{'Mana':25},resistances=['fire'],vulnerabilities=['ice'])
    add('Frostbound Favor',g,'You endure ice unusually well, while heat finds every weakness. The protection is narrow and does not remove the need for shelter.',{}, {'Ice Magic':4},{'Mana':25},resistances=['ice'],vulnerabilities=['fire'])
    add('Storm-Bound Spark',g,'Lightning finds less purchase in you, but grounding force is a danger. The gift is noticeable in the work you choose, not a compulsory visible mark.',{}, {'Lightning Magic':4},{'Stamina':15},resistances=['lightning'],vulnerabilities=['earth'])
    add('Iron Lotus Constitution',g,'A remarkably tough body supports guarding and physical work at the cost of a smaller usable Mana reserve.',{'force':2},{'Guarded Combat':3},{'Health':45,'Mana':-30})
    add('Paper Lantern Body',g,'Magic comes easily through a light, fragile constitution. Your physical appearance remains individually chosen.',{'intuition':2},{'spellcraft':4},{'Mana':40,'Health':-30,'Stamina':-10})
    add('Red Thread Covenant',g,'A limited healing gift supports a real act of care for another person. It creates no compulsory romance, master or distant bonded stranger.',{'empathy':1},{'Healing Magic':4},{'Mana':15},ability=move('Crimson Thread, Gentle Knot','Attempt basic Healing Magic on one reachable living patient, using this bonus. A successful result restores the normal basic amount once under Health instructions. Actual condition and limits apply; the working cannot reverse death or aging. Costs 12 Mana.',5,6))
    add('Covenant of the Small Guest',g,'You have learned one modest summoning pattern and a patient way of maintaining it. A summoned helper is not an independently owned pet or new named NPC.',{'empathy':1},{'Summoning Magic':4},{'Mana':15},ability=move('Little Door, Little Guest','Summon one temporary palm-sized noncombat helper for a simple nearby task such as carrying a light object or retrieving an accessible dropped tool. Resolve Summoning Magic with this bonus when uncertain. No attack, scouting through sealed walls, permanent materials or duplicate helpers. Costs 12 Mana; the helper departs when this immediate task ends.',5,6))
    add('Soul-Lantern Keeper',g,'You can sense a faint nearby spiritual trace through a narrow learned Soul working. A trace is evidence to interpret, not an obedient conscious spirit.',{'empathy':1},{'Soul Magic':4,'Insight':2},ability=move('Lantern for an Echo','Examine one actual nearby spiritual residue or attempt a modest spiritual ward using Soul Magic with this bonus. Preserve uncertainty about identity and cause. No involuntary soul extraction, automatic possession cure or raising the dead. Costs 12 Mana.',5,6))
    add('Golden Burden',g,'A forceful gift makes your decisions carry unusual conviction, but sustaining it leaves less room for physical exertion. It grants no title or guaranteed obedience.',{'passion':2},{'persuasion':4,'intimidation':3},{'Stamina':-20})
    add('Hundred-Tool Instinct',g,'An exceptional practical imagination helps you see alternatives in the equipment you truly have. Long concentration is easier than brute effort.',{'logic':2},{'Magitech':5,'Alchemy':3},{'Stamina':-20},ability=move('A Better Use for This','Attempt one plausible improvised repair or adaptation with actual equipment, available materials and the relevant Magitech method. Apply this bonus once. It creates no absent tool, permanent new enchantment, free item or automatic quality upgrade. Costs 8 Stamina.',6,6))
    assert len(rows)==48
    return rows
